16	/// Returns true if:
17	/// - `next_comment` is Some, and
18	/// - both comments are documentation comments, and
19	/// - both comments are multiline, and
20	/// - the two comments are immediately adjacent to each other, with no characters between them.
21	///
22	/// In this case, the comments are considered "nestled" - a pattern that JSDoc uses to represent
23	/// overloaded types, which get merged together to create the final type for the subject. The
24	/// comments must be kept immediately adjacent after formatting to preserve this behavior.
25	///
26	/// There isn't much documentation about this behavior, but it is mentioned on the JSDoc repo
27	/// for documentation: <https://github.com/jsdoc/jsdoc.github.io/issues/40>. Prettier also
28	/// implements the same behavior: <https://github.com/prettier/prettier/pull/13445/files#diff-3d5eaa2a1593372823589e6e55e7ca905f7c64203ecada0aa4b3b0cdddd5c3ddR160-R178>
29	pub fn should_nestle_adjacent_doc_comments<L: Language>(
30	    first_comment: &SourceComment<L>,
31	    second_comment: &SourceComment<L>,
32	) -> bool {
33	    let first = first_comment.piece();
34	    let second = second_comment.piece();
35	
36	    first.has_newline()
37	        && second.has_newline()
38	        && (second.text_range().start()).sub(first.text_range().end()) == TextSize::from(0)
39	        && is_doc_comment(first)
40	        && is_doc_comment(second)
41	}
