++    fn fmt_trailing_comments(
++        &self,
++        _node: &CssGenericProperty,
++        _f: &mut CssFormatter,
++    ) -> FormatResult<()> {
++        // Trailing comments are formatted inline in fmt_fields
++        Ok(())
